arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "channel=C_INC&limit=200" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d.get('error'), d.get('response_metadata'))
for m in d.get('messages',[]):
    t=m.get('text','')
    if 'payment' in t.lower() or 'gateway' in t.lower() or 'outage' in t.lower():
        print(m['ts'], '|', t[:200].replace(chr(10),' / '))
"

